type ReturningCapture<'a> = dyn for<'row> FnMut(&Storage, u32, &dyn SequenceAccess, &[Datum<'row>]) -> Result<(), SqlError>
    + 'a;

fn intrinsic_uuid_parameter_oids(
    written_name: &str,
    argument_names: &[Option<&str>],
    variadic: bool,
    argument_count: usize,
) -> Option<[i32; crate::storage::MAX_ROUTINE_ARGUMENTS]> {
    let name = match written_name.split_once('.') {
        Some(("pg_catalog", name)) => name,
        Some(_) => return None,
        None => written_name,
    };
    if variadic || argument_count != 1 {
        return None;
    }
    let positional = argument_names.is_empty() || argument_names.iter().all(Option::is_none);
    let expected = if name.eq_ignore_ascii_case("uuidv7")
        && (positional
            || matches!(argument_names, [Some(argument)] if argument.eq_ignore_ascii_case("shift")))
    {
        types::oid::INTERVAL
    } else if matches!(name, "uuid_extract_timestamp" | "uuid_extract_version") && positional {
        types::oid::UUID
    } else {
        return None;
    };
    let mut oids = [types::oid::UNKNOWN; crate::storage::MAX_ROUTINE_ARGUMENTS];
    oids[0] = expected;
    Some(oids)
}

/// Complete durable input for binding one startup-reserved subscription worker.
/// Values are copied out of the catalog so the reactor never holds a catalog
/// borrow while it drives a network socket or applies a remote transaction.
#[derive(Clone, Copy)]
pub(crate) struct SubscriptionRuntime {
    pub stream: crate::storage::SubscriptionStream,
    pub endpoint: crate::pg::replication_client::SubscriptionEndpoint,
    pub publications: [SqlName; crate::storage::MAX_SUBSCRIPTION_PUBLICATIONS],
    pub publication_count: usize,
    pub slot: Option<SqlName>,
    pub manage_slot_behavior: bool,
    pub bootstrap_slot: Option<SqlName>,
    pub drop_bootstrap_slot: bool,
    pub confirmed_lsn: u64,
    pub bootstrap: crate::storage::SubscriptionBootstrap,
    pub enabled: bool,
    pub behavior: crate::storage::SubscriptionBehavior,
}

#[derive(Clone, Copy)]
pub(crate) struct SubscriptionCleanupRuntime {
    pub created_at: u64,
    pub name: SqlName,
    pub endpoint: crate::pg::replication_client::SubscriptionEndpoint,
    pub slot: SqlName,
}

#[derive(Debug)]
pub enum EngineSetupError {
    Configuration(&'static str),
    ResourceConfiguration(crate::config::ConfigError),
    Budget(BudgetError),
    Wal(WalSetupError),
    Checkpoint(CheckpointSetupError),
    /// A storage operation during recovery failed loudly — e.g. the recovered
    /// data exceeds the configured value-index capacity.
    Storage(SqlError),
    ForeignTransport(String),
    TriggerEventSpill(trigger_events::TriggerEventSpillError),
}

impl From<SqlError> for EngineSetupError {
    fn from(e: SqlError) -> Self {
        Self::Storage(e)
    }
}

impl std::fmt::Display for EngineSetupError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Configuration(message) => f.write_str(message),
            Self::ResourceConfiguration(error) => write!(f, "{error}"),
            Self::Budget(e) => write!(f, "{e}"),
            Self::Wal(e) => write!(f, "{e}"),
            Self::Checkpoint(e) => write!(f, "{e}"),
            Self::Storage(e) => write!(f, "{}", e.message.as_str()),
            Self::ForeignTransport(e) => write!(f, "{e}"),
            Self::TriggerEventSpill(e) => write!(f, "{e}"),
        }
    }
}

impl From<CheckpointSetupError> for EngineSetupError {
    fn from(e: CheckpointSetupError) -> Self {
        Self::Checkpoint(e)
    }
}

impl std::error::Error for EngineSetupError {}

impl From<BudgetError> for EngineSetupError {
    fn from(e: BudgetError) -> Self {
        Self::Budget(e)
    }
}

impl From<crate::config::ConfigError> for EngineSetupError {
    fn from(error: crate::config::ConfigError) -> Self {
        Self::ResourceConfiguration(error)
    }
}

impl From<crate::storage::StorageSetupError> for EngineSetupError {
    fn from(error: crate::storage::StorageSetupError) -> Self {
        match error {
            crate::storage::StorageSetupError::Budget(error) => Self::Budget(error),
            crate::storage::StorageSetupError::Configuration(error) => {
                Self::ResourceConfiguration(error)
            }
            crate::storage::StorageSetupError::LeasePool(error) => Self::Storage(sql_err!(
                crate::sql::eval::sqlstate::INVALID_PARAMETER_VALUE,
                "{}",
                error
            )),
            crate::storage::StorageSetupError::ValueIndex(error) => Self::Storage(sql_err!(
                crate::sql::eval::sqlstate::INVALID_PARAMETER_VALUE,
                "{}",
                error
            )),
            crate::storage::StorageSetupError::Metadata(error) => Self::Storage(error),
            crate::storage::StorageSetupError::CatalogIdentitySpaceExhausted => {
                Self::Storage(sql_err!(
                    crate::sql::eval::sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "catalog reference identity space exhausted"
                ))
            }
        }
    }
}

impl From<WalSetupError> for EngineSetupError {
    fn from(e: WalSetupError) -> Self {
        Self::Wal(e)
    }
}

