struct QueryWorkspaces {
    slots: FixedVec<QueryWorkspace>,
}

struct QueryWorkspace {
    arena: Arena,
    /// Images of the catalog relations a statement reads under its catalog
    /// snapshot; reset when a top-level statement starts.
    catalog_images: Arena,
    row_cursor_buffers: crate::storage::RowCursorBuffers,
    connection_id: i32,
    database_oid: crate::storage::DatabaseOid,
}

/// Index of one startup-reserved query workspace. The server leases these
/// identities explicitly so two dispatch workers cannot select the same arena
/// or DML scratch through a coincidental connection-id mapping.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct QueryWorkspaceId(usize);

impl QueryWorkspaceId {
    pub(crate) const fn from_index(index: usize) -> Self {
        Self(index)
    }

    pub(crate) const fn index(self) -> usize {
        self.0
    }
}

fn set_execution_query_workspace(workspace: QueryWorkspaceId) {
    EXECUTION_QUERY_WORKSPACE.with(|active| active.set(workspace.index()));
}

pub(crate) fn execution_query_workspace() -> QueryWorkspaceId {
    QueryWorkspaceId::from_index(EXECUTION_QUERY_WORKSPACE.with(core::cell::Cell::get))
}

pub(crate) fn reset_execution_query_workspace() {
    set_execution_query_workspace(QueryWorkspaceId::from_index(0));
}

struct DmlWorkspaces {
    slots: FixedVec<exec::DmlScratch>,
}

impl DmlWorkspaces {
    fn new(
        config: &Config,
        budget: &mut Budget,
        row_work: &std::sync::Arc<crate::mem::lease_pool::LeasePool>,
    ) -> Result<Self, BudgetError> {
        let mut slots =
            FixedVec::new(budget, "query_dml_workspaces", config.query_workspace_slots)?;
        for _ in 0..config.query_workspace_slots {
            slots
                .push(
                    row_work
                        .lease(0)
                        .expect("empty write lease needs no capacity"),
                )
                .expect("sized to query_workspace_slots");
        }
        Ok(Self { slots })
    }
}

impl core::ops::Deref for DmlWorkspaces {
    type Target = exec::DmlScratch;

    fn deref(&self) -> &Self::Target {
        &self.slots[execution_query_workspace().index()]
    }
}

impl core::ops::DerefMut for DmlWorkspaces {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.slots[execution_query_workspace().index()]
    }
}

impl QueryWorkspaces {
    fn new(config: &Config, budget: &mut Budget) -> Result<Self, BudgetError> {
        reset_execution_query_workspace();
        let mut slots = FixedVec::new(budget, "query_workspaces", config.query_workspace_slots)?;
        for _ in 0..config.query_workspace_slots {
            slots
                .push(QueryWorkspace {
                    arena: Arena::new(budget, "query_workspace_arena", config.work_arena_bytes)?,
                    catalog_images: Arena::new(
                        budget,
                        "catalog_image_arena",
                        config.catalog_image_bytes,
                    )?,
                    row_cursor_buffers: crate::storage::RowCursorBuffers::new(config, budget)?,
                    connection_id: 0,
                    database_oid: crate::storage::DatabaseOid::POSTGRES,
                })
                .expect("sized to query_workspace_slots");
        }
        Ok(Self { slots })
    }

    fn select(&self, workspace: QueryWorkspaceId) {
        assert!(workspace.index() < self.slots.len());
        set_execution_query_workspace(workspace);
        set_execution_connection_id(self.slots[workspace.index()].connection_id);
        set_execution_database_oid(self.slots[workspace.index()].database_oid);
    }

    fn for_connection(&self, connection: i32) -> QueryWorkspaceId {
        let connection = usize::try_from(connection).unwrap_or(0);
        QueryWorkspaceId(connection % self.slots.len())
    }

    fn bind_connection(&mut self, connection_id: i32) {
        self.slots[execution_query_workspace().index()].connection_id = connection_id;
        set_execution_connection_id(connection_id);
    }

    fn connection_id(&self) -> i32 {
        self.slots[execution_query_workspace().index()].connection_id
    }

    fn bind_database_oid(&mut self, database: crate::storage::DatabaseOid) {
        self.slots[execution_query_workspace().index()].database_oid = database;
        set_execution_database_oid(database);
    }

    fn database_oid(&self) -> crate::storage::DatabaseOid {
        self.slots[execution_query_workspace().index()].database_oid
    }
    /// The selected workspace's statement catalog image arena.
    fn catalog_images(&self) -> &Arena {
        &self.slots[execution_query_workspace().index()].catalog_images
    }

    fn reset_catalog_images(&mut self) {
        self.slots[execution_query_workspace().index()]
            .catalog_images
            .reset();
    }

    fn cursor_parts(&mut self) -> (&Arena, &mut crate::storage::RowCursorBuffers) {
        let workspace = &mut self.slots[execution_query_workspace().index()];
        (&workspace.arena, &mut workspace.row_cursor_buffers)
    }
    /// The selected workspace's cursor scan buffers, which the triggers a
    /// statement fires read session cursors with.
    fn row_cursor_buffers(&mut self) -> &mut crate::storage::RowCursorBuffers {
        &mut self.slots[execution_query_workspace().index()].row_cursor_buffers
    }
}

impl core::ops::Deref for QueryWorkspaces {
    type Target = Arena;

    fn deref(&self) -> &Self::Target {
        &self.slots[execution_query_workspace().index()].arena
    }
}

impl core::ops::DerefMut for QueryWorkspaces {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.slots[execution_query_workspace().index()].arena
    }
}

