/// The query engine: catalog, memtable storage, WAL, object-storage
/// checkpointing, and statement execution.
pub struct Engine {
    storage: Storage,
    wal: Wal,
    /// Per-connection retained-read allocation for resuming large results.
    result_stream_bytes: usize,
    /// Saved generations a table scan can retain, bounding a stream's capture.
    max_spill_generations_per_table: usize,
    result_streams_opened: u64,
    result_streams_spooled: [u64; 3],
    ckpt: Option<Checkpointer>,
    temporary_spiller: Option<TemporarySpiller>,
    /// Shared overflow file for connections' queued AFTER trigger events.
    trigger_event_spill: Option<trigger_events::SharedTriggerEventSpill>,
    /// A durable, installed manifest whose heap and journal cleanup remains.
    /// Cleanup retries preserve the publication's captured log boundary.
    local_cleanup: Option<LocalCleanup>,
    checkpoint_failure: Option<(u64, SqlError)>,
    cache_capacity_generation: u64,
    cache_capacity_failure: Option<(u64, SqlError)>,
    /// A COPY FROM STDIN the last statement started: the connection takes
    /// it, switches into copy-in mode, and feeds data lines back through
    /// [`Engine::copy_row_line`] until CopyDone.
    pending_copy: Option<(exec::CopySetup, i64)>,
    /// A COPY FROM refused once the client sends its data (see
    /// [`exec::CopyRefusal`]).
    pending_copy_refusal: Option<(exec::CopyRefusal, i64)>,
    /// A promoted statement's source range and plan owner, taken by the
    /// connection to reopen it as a result stream.
    pending_result_stream: Option<PendingResultStream>,
    wal_upload: bool,
    commit_progress: CommitProgressMode,
    inflight_publication: Option<InflightPublication>,
    publication_failed: bool,
    durable_lsn: u64,
    unpromoted_commits: usize,
    fatal_commit_failure: Option<SqlError>,
    transaction_publication: commit::PublicationState,
    #[cfg(test)]
    publication_observer: Option<(commit::PublicationObserver, u32)>,
    commit_queue: Option<commit::Queue>,
    read_owner: Option<crate::store::ReadOwner>,
    /// Scratch buffer for reading committed WAL batches before the
    /// provider-neutral object PUT.
    wal_seg_buf: Vec<u8>,
    /// Scratch for sorting SST entries at checkpoint.
    scratch: FixedVec<(u64, RowHome)>,
    /// Startup-bounded slot-private physical-row identities selected by DML.
    /// Kept separate from checkpoint sort entries because a logical
    /// partitioned relation needs its leaf owner alongside the row identifier.
    dml_scratch: DmlWorkspaces,
    statistics_receipts: std::sync::Arc<crate::storage::StatisticsReceiptPool>,
    /// Scratch for heap compaction: every live row image across tables.
    compact_scratch: crate::storage::HeapRelocationWorkspace,
    /// Startup-bounded slot-private execution arenas. The reactor still
    /// serializes execution, but statements no longer depend on one global
    /// workspace identity; worker parallelism can use these slots without
    /// introducing runtime allocation.
    work: QueryWorkspaces,
    max_connections: u32,
    max_prepared_transactions: usize,
    max_locks_per_transaction: usize,
    commit_altered_tables: FixedVec<(usize, bool)>,
    commit_index_tables: FixedVec<usize>,
    logical_decoding_truncates: FixedVec<PendingTruncate>,
    logical_decoding_truncate_tables: FixedVec<u16>,
    logical_decoding_truncate_relations: FixedVec<u32>,
    prepared_transactions: two_phase::PreparedTransactions,
    /// LISTEN/NOTIFY registry and delivery outbox, shared across every
    /// connection (see [`notify`]).
    notify: notify::NotifyState,
    /// Stable identity exposed by the replication protocol. It is derived
    /// from the durable namespace rather than process-local state, so a
    /// restarted or cold-recovered server remains the same publisher.
    replication_system_id: u64,
    /// Authenticated sessions per fixed role slot, used to enforce
    /// `CONNECTION LIMIT` without allocating in the server loop.
    role_connections: FixedVec<RoleConnections>,
    database_connections: FixedVec<u16>,
    active_system_settings: ActiveSystemSettings,
    object_store_credentials_reload_requested: bool,
    protocol_reset: ProtocolReset,
    clean_shutdown_path: std::path::PathBuf,
    #[cfg(test)]
    _test_data_dir_cleanup: Option<std::sync::Arc<crate::config::TestDataDirCleanup>>,
}

