#[derive(Clone, Copy)]
struct ActiveSystemSetting {
    name: crate::storage::SqlName,
    value: crate::util::StackStr<{ crate::storage::ROLE_SETTING_VALUE_MAX }>,
}

struct ActiveSystemSettings {
    image: Mutex<ActiveSystemSettingsImage>,
}

struct ActiveSystemSettingsImage {
    entries: [Option<ActiveSystemSetting>; crate::storage::MAX_SYSTEM_SETTINGS],
    reloaded: bool,
}

impl ActiveSystemSettings {
    fn new(entries: [Option<ActiveSystemSetting>; crate::storage::MAX_SYSTEM_SETTINGS]) -> Self {
        Self {
            image: Mutex::new(ActiveSystemSettingsImage {
                entries,
                reloaded: false,
            }),
        }
    }

    fn replace(&self, entries: [Option<ActiveSystemSetting>; crate::storage::MAX_SYSTEM_SETTINGS]) {
        *self
            .image
            .lock()
            .expect("active system settings lock poisoned") = ActiveSystemSettingsImage {
            entries,
            reloaded: true,
        };
    }

    fn apply(&self, guc: &GucState) -> Result<(), SqlError> {
        let image = self
            .image
            .lock()
            .expect("active system settings lock poisoned")
            .entries;
        guc.reset_cluster_defaults();
        for setting in image.iter().flatten() {
            guc.set_cluster_default(setting.name.as_str(), setting.value.as_str())?;
        }
        Ok(())
    }

    fn take_reload(&self) -> bool {
        core::mem::take(
            &mut self
                .image
                .lock()
                .expect("active system settings lock poisoned")
                .reloaded,
        )
    }
}

struct ConfigurationReloadScope {
    engine: *mut Engine,
    guc: *const GucState,
}

impl ConfigurationReloadScope {
    fn new(engine: &mut Engine, guc: &GucState) -> Self {
        eval::funcs::system::clear_configuration_reload_request();
        Self { engine, guc }
    }
}

impl Drop for ConfigurationReloadScope {
    fn drop(&mut self) {
        if !eval::funcs::system::take_configuration_reload_request() {
            return;
        }
        // The scope drops after statement evaluation has released every
        // Engine and GUC borrow; the pointers refer to its enclosing call.
        let engine = unsafe { &mut *self.engine };
        let guc = unsafe { &*self.guc };
        engine.reload_system_settings();
        engine.object_store_credentials_reload_requested = true;
        engine
            .apply_system_settings(guc)
            .expect("stored system settings were validated before publication");
    }
}

